// Shared helpers for the pyzig-fuzz subject drivers.
//
// A driver is a standalone Zig program: it reads a file of hex-encoded cases
// (one per line), runs each case through the corpus recipe and writes one
// observation per line:
//
//     <status>\t<hex(packed fields)>
//
// The packed fields are the schema's compared fields, in the order fixed by
// the corpus contract (`fuzz.compared_fields`). The driver is generated by
// `pyzig-fuzz prepare`, which injects the recipe implementation from the
// corpus into the `// @IMPL@` marker.
const std = @import("std");

pub const Fields = struct {
    buf: []const u8,
    pos: usize = 0,

    pub fn init(buf: []const u8) Fields {
        return .{ .buf = buf };
    }

    pub fn next(self: *Fields) ?[]const u8 {
        if (self.pos + 4 > self.buf.len) return null;
        const len = std.mem.readInt(u32, self.buf[self.pos..][0..4], .little);
        self.pos += 4;
        if (self.pos + len > self.buf.len) return null;
        const f = self.buf[self.pos .. self.pos + len];
        self.pos += len;
        return f;
    }
};

pub fn hexEncode(gpa: std.mem.Allocator, bytes: []const u8) ![]u8 {
    const digits = "0123456789abcdef";
    const out = try gpa.alloc(u8, bytes.len * 2);
    for (bytes, 0..) |b, i| {
        out[2 * i] = digits[b >> 4];
        out[2 * i + 1] = digits[b & 0x0f];
    }
    return out;
}

pub fn hexDecode(gpa: std.mem.Allocator, hex: []const u8) ![]u8 {
    if (hex.len % 2 != 0) return error.BadHex;
    const out = try gpa.alloc(u8, hex.len / 2);
    errdefer gpa.free(out);
    _ = std.fmt.hexToBytes(out, hex) catch return error.BadHex;
    return out;
}

pub fn packFields(gpa: std.mem.Allocator, fields: []const []const u8) ![]u8 {
    var total: usize = 0;
    for (fields) |f| total += 4 + f.len;
    const out = try gpa.alloc(u8, total);
    errdefer gpa.free(out);
    var pos: usize = 0;
    for (fields) |f| {
        std.mem.writeInt(u32, out[pos..][0..4], @intCast(f.len), .little);
        pos += 4;
        @memcpy(out[pos..][0..f.len], f);
        pos += f.len;
    }
    return out;
}

/// Read the case file: one hex payload per line.
pub fn readCases(gpa: std.mem.Allocator, io: std.Io, path: []const u8) ![][]u8 {
    const content = try std.Io.Dir.cwd().readFileAlloc(io, path, gpa, .limited(256 * 1024 * 1024));
    defer gpa.free(content);

    var out: std.ArrayList([]u8) = .empty;
    errdefer {
        for (out.items) |p| gpa.free(p);
        out.deinit(gpa);
    }
    var it = std.mem.splitScalar(u8, content, '\n');
    while (it.next()) |line| {
        const t = std.mem.trim(u8, line, " \t\r");
        if (t.len == 0) continue;
        const payload = try hexDecode(gpa, t);
        errdefer gpa.free(payload);
        try out.append(gpa, payload);
    }
    return out.toOwnedSlice(gpa);
}

pub fn freeCases(gpa: std.mem.Allocator, cases: [][]u8) void {
    for (cases) |c| gpa.free(c);
    gpa.free(cases);
}

/// Append one observation line to the output buffer.
pub fn appendObs(gpa: std.mem.Allocator, out: *std.ArrayList(u8), status: []const u8, values: []const []const u8) !void {
    const payload = try packFields(gpa, values);
    defer gpa.free(payload);
    const hex = try hexEncode(gpa, payload);
    defer gpa.free(hex);
    try out.print(gpa, "{s}\t{s}\n", .{ status, hex });
}

/// Write the observation file.
pub fn writeObs(gpa: std.mem.Allocator, io: std.Io, path: []const u8, bytes: []const u8) !void {
    _ = gpa;
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = path, .data = bytes });
}

/// Canonical error names shared with the Python reference models.
pub fn canonError(err: anyerror) []const u8 {
    return switch (err) {
        error.FileNotFound => "FileNotFound",
        error.IsDir => "IsDir",
        error.NotDir => "NotDir",
        error.StreamTooLong => "StreamTooLong",
        error.AccessDenied, error.PermissionDenied => "PermissionDenied",
        error.Timeout => "Timeout",
        error.InvalidArgument => "InvalidArgument",
        error.OutOfMemory => "OutOfMemory",
        error.NoSpaceLeft => "NoSpaceLeft",
        else => "Unknown",
    };
}

/// A case is invalid for the recipe: both sides must reject it the same way.
pub fn invalid(gpa: std.mem.Allocator, out: *std.ArrayList(u8), n_fields: usize) !void {
    var values: std.ArrayList([]const u8) = .empty;
    defer values.deinit(gpa);
    try values.append(gpa, "invalid");
    try values.append(gpa, "InvalidArgument");
    var i: usize = 2;
    while (i < n_fields) : (i += 1) try values.append(gpa, "");
    try appendObs(gpa, out, "invalid", values.items);
}

/// Case field validation shared by the drivers.
pub fn validPath(path: []const u8) bool {
    if (path.len == 0) return false;
    if (path.len > 255) return false;
    if (std.mem.indexOfScalar(u8, path, 0) != null) return false;
    if (path[0] == '/') return false;
    if (std.mem.indexOf(u8, path, "..") != null) return false;
    return true;
}

pub fn validProgram(prog: []const u8) bool {
    if (prog.len == 0) return false;
    if (prog.len > 64) return false;
    if (std.mem.indexOfScalar(u8, prog, 0) != null) return false;
    if (std.mem.indexOfScalar(u8, prog, '/') != null) return false;
    return true;
}

pub fn validArg(arg: []const u8) bool {
    return std.mem.indexOfScalar(u8, arg, 0) == null;
}

/// Parse a KV line: returns key/value slices (allocated) or null if the line
/// is empty, a comment, or has no '='.  Caller must free kv.key and kv.val.
pub const KV = struct {
    key: []u8,
    val: []u8,
};

pub fn parseLineAlloc(gpa: std.mem.Allocator, line: []const u8) !?KV {
    const trimmed = std.mem.trim(u8, line, " \t");
    if (trimmed.len == 0 or trimmed[0] == '#') return null;
    const eq = std.mem.indexOfScalar(u8, trimmed, '=') orelse return null;
    const key = std.mem.trim(u8, trimmed[0..eq], " \t");
    const val = std.mem.trim(u8, trimmed[eq + 1 ..], " \t");
    // Remove surrounding single quotes if present
    const val_trimmed = if (val.len >= 2 and val[0] == '\'' and val[val.len - 1] == '\'')
        val[1..val.len - 1]
    else
        val;
    const k = try gpa.dupe(u8, key);
    const v = try gpa.dupe(u8, val_trimmed);
    return .{ .key = k, .val = v };
}
